Object.assign(STRINGS.de, { vi_prev_same: 'Gleicher Prüfpunkt kürzlich repariert', vi_prev_same_hint: 'Derselbe Mangel wurde an diesem Fahrzeug in den 90 Tagen vor dieser Meldung schon einmal behoben – Ursache prüfen (z. B. Nacharbeit, Teilequalität).' });
Object.assign(STRINGS.uk, { vi_prev_same: 'Той самий пункт нещодавно ремонтували', vi_prev_same_hint: 'Цей самий дефект на цьому транспорті вже усували протягом 90 днів до цього повідомлення – перевірте причину (наприклад, доопрацювання, якість запчастин).' });
