Object.assign(STRINGS.de, { claim_title: 'Versicherungsfall', claim_none: 'Kein Versicherungsfall erfasst.', claim_add: 'Versicherungsfall erfassen', claim_edit: 'Versicherungsfall ändern', claim_contract: 'Versicherungsvertrag', claim_no_contract: '– ohne Vertrag (Versicherer eintragen) –', claim_insurer: 'Versicherer', claim_insurer_hint: 'leer = Vertragspartner des gewählten Vertrags', claim_no: 'Schadennummer', claim_reported: 'Gemeldet am', claim_days_open: 'seit {n} Tag(en) offen', claim_deductible: 'Selbstbeteiligung netto (laut Vertrag/Schreiben)', claim_reimbursed: 'Erstattung netto (laut Abrechnung)', claim_reimbursed_on: 'Erstattet am', claim_hint: 'Alle Angaben laut Schadenmeldung bzw. Schreiben/Abrechnung des Versicherers. Erstattung nur mit Datum; bei „abgelehnt“/„zurückgezogen“ keine Erstattung.', claims: 'Versicherungsfälle', claims_hint: 'Schäden, die dem Versicherer gemeldet wurden – mit Status, Erstattung und Saldo (belegte Kosten des Vorgangs minus Erstattung; nur wenn beides belegt ist). Erfassen im jeweiligen Vorgang.', claim_f_open: 'Offen', claim_sum: 'Summe Erstattungen (Auswahl)', claims_none: 'Keine Versicherungsfälle.', claim_case_cost: 'Kosten belegt', claim_balance: 'Saldo', claim_deductible_short: 'SB', claim_reimbursed_short: 'erstattet', cls_gemeldet: 'Gemeldet', cls_in_pruefung: 'In Prüfung', cls_reguliert: 'Reguliert', cls_abgelehnt: 'Abgelehnt', cls_zurueckgezogen: 'Zurückgezogen',
  help_claims_t: 'Fuhrparkleitung: Versicherungsfälle', help_claims_s: 'Im Vorgang (z. B. Unfall) „Versicherungsfall erfassen“: Versicherungsvertrag wählen oder Versicherer eintragen, Meldedatum und Nachweis sind Pflicht.|Schadennummer, Selbstbeteiligung und Status nur laut Schreiben des Versicherers eintragen.|Erstattung mit Betrag und Datum laut Abrechnung – der Saldo (belegte Kosten minus Erstattung) erscheint unter Mehr → Versicherungsfälle.|Die Übersicht zeigt offene Fälle mit „seit … Tagen offen“ und lässt sich als CSV exportieren.|Meldung und Erstattung stehen in der Zeitleiste der Fahrzeugakte; Erstattungen zeigt der Kostenbericht getrennt (nicht von den Kosten abgezogen).|Datenqualität weist auf Vorgänge hin, deren Beschreibung „Unfall“ nennt, aber noch keinen Versicherungsfall haben.|Erinnerung zum Nachfassen beim Versicherer: Inhaber trägt unter Einstellungen die Tage ein (leer = aus).' });
Object.assign(STRINGS.uk, { claim_title: 'Страховий випадок', claim_none: 'Страховий випадок не зареєстровано.', claim_add: 'Зареєструвати страховий випадок', claim_edit: 'Змінити страховий випадок', claim_contract: 'Договір страхування', claim_no_contract: '– без договору (вкажіть страховика) –', claim_insurer: 'Страховик', claim_insurer_hint: 'порожньо = контрагент обраного договору', claim_no: 'Номер збитку', claim_reported: 'Повідомлено', claim_days_open: 'відкрито {n} дн.', claim_deductible: 'Франшиза нетто (згідно з договором/листом)', claim_reimbursed: 'Відшкодування нетто (згідно з розрахунком)', claim_reimbursed_on: 'Відшкодовано', claim_hint: 'Усі дані згідно з повідомленням про збиток або листом/розрахунком страховика. Відшкодування лише з датою; при «відхилено»/«відкликано» відшкодування не вносити.', claims: 'Страхові випадки', claims_hint: 'Збитки, про які повідомлено страховика, – зі статусом, відшкодуванням і сальдо (підтверджені витрати мінус відшкодування; лише якщо обидва підтверджені). Реєстрація у відповідному зверненні.', claim_f_open: 'Відкриті', claim_sum: 'Сума відшкодувань (вибірка)', claims_none: 'Страхових випадків немає.', claim_case_cost: 'Витрати підтверджені', claim_balance: 'Сальдо', claim_deductible_short: 'Франшиза', claim_reimbursed_short: 'відшкодовано', cls_gemeldet: 'Повідомлено', cls_in_pruefung: 'На розгляді', cls_reguliert: 'Врегульовано', cls_abgelehnt: 'Відхилено', cls_zurueckgezogen: 'Відкликано',
  help_claims_t: 'Керівник автопарку: страхові випадки', help_claims_s: 'У зверненні (напр. ДТП) «Зареєструвати страховий випадок»: оберіть договір страхування або вкажіть страховика; дата повідомлення і підтвердження обов’язкові.|Номер збитку, франшизу і статус вносити лише згідно з листом страховика.|Відшкодування з сумою і датою згідно з розрахунком – сальдо (підтверджені витрати мінус відшкодування) видно в Більше → Страхові випадки.|Огляд показує відкриті випадки з «відкрито … дн.» і експортується як CSV.|Повідомлення і відшкодування видно на часовій шкалі картки авто; звіт витрат показує відшкодування окремо (не віднімаються від витрат).|Якість даних вказує на звернення, в описі яких згадано «ДТП», але ще немає страхового випадку.|Нагадування звернутися до страховика: власник вказує кількість днів у Налаштуваннях (порожньо = вимк.).' });
Object.assign(STRINGS.en, { claim_title: 'Insurance claim', claim_none: 'No insurance claim recorded.', claim_add: 'Record insurance claim', claim_edit: 'Edit insurance claim', claim_contract: 'Insurance contract', claim_no_contract: '– no contract (enter insurer) –', claim_insurer: 'Insurer', claim_insurer_hint: 'empty = partner of the selected contract', claim_no: 'Claim number', claim_reported: 'Reported on', claim_days_open: 'open for {n} day(s)', claim_deductible: 'Deductible, net (per contract/letter)', claim_reimbursed: 'Reimbursement, net (per settlement)', claim_reimbursed_on: 'Reimbursed on', claim_hint: 'All data as per the claim report or the insurer’s letter/settlement. Reimbursement only with a date; none for “rejected”/“withdrawn”.', claims: 'Insurance claims', claims_hint: 'Damage reported to the insurer – with status, reimbursement and balance (documented costs of the case minus reimbursement; only when both are documented). Record it in the case.', claim_f_open: 'Open', claim_sum: 'Total reimbursements (selection)', claims_none: 'No insurance claims.', claim_case_cost: 'Documented costs', claim_balance: 'Balance', claim_deductible_short: 'Deductible', claim_reimbursed_short: 'reimbursed', cls_gemeldet: 'Reported', cls_in_pruefung: 'Under review', cls_reguliert: 'Settled', cls_abgelehnt: 'Rejected', cls_zurueckgezogen: 'Withdrawn',
  help_claims_t: 'Fleet management: insurance claims', help_claims_s: 'In the case (e.g. accident) use “Record insurance claim”: select the insurance contract or enter the insurer; reporting date and evidence are required.|Enter claim number, deductible and status only as stated in the insurer’s letter.|Enter the reimbursement with amount and date per the settlement – the balance (documented costs minus reimbursement) appears under More → Insurance claims.|The overview shows open claims with “open for … days” and can be exported as CSV.|Reporting and reimbursement appear in the vehicle file timeline; the cost report lists reimbursements separately (not deducted from costs).|Data quality points out cases whose description mentions “accident” but have no insurance claim yet.|Follow-up reminder with the insurer: the owner enters the number of days under Settings (empty = off).' });
