Object.assign(STRINGS.de, { kpi_pe: 'Termintreue Teile-Liefertermine', kpi_pe_kept: 'eingehalten', kpi_pe_late: 'überschritten', kpi_pe_on_time: 'pünktlich', kpi_pe_median: 'Verspätung Median', kpi_pe_open: 'überschritten, noch offen', kpi_pe_without: 'ohne Liefertermin', kpi_pe_nosite: 'ohne Werkstatt', kpi_pe_rule: 'Je Warten auf Teile: zuletzt eingetragener Liefertermin (laut Werkstatt/Lieferant) gegen „Reparatur fortgesetzt“. Eingehalten = am oder vor dem Termin. Ohne Liefertermin nur gezählt. Bewertet wird die Lieferung, keine Person.', plan_before_parts: 'Termin vor Liefertermin der Teile' });
