Object.assign(STRINGS.de, { cost_approval_pending: 'Kostenfreigabe ausstehend', cost_approval_hint_mgr: 'Die bewerteten Kosten (Ist + Schätzung) liegen über der eingestellten Freigabegrenze bzw. dem zuletzt freigegebenen Betrag. Bitte prüfen und „Kosten freigeben“.', cost_approval_hint_ws: 'Die Kosten liegen über der Freigabegrenze. Bitte vor weiteren größeren Arbeiten/Bestellungen die Freigabe der Fuhrparkleitung abwarten (sicherheitsrelevante Arbeiten nicht aufschieben).', cost_limit: 'Freigabegrenze', cost_approved_upto: 'freigegeben bis', act_approve_costs: 'Kosten freigeben', act_cost_limit_exceeded: 'Kosten über Freigabegrenze', cost_approve_hint: 'Gibt den aktuellen Betrag frei. Steigen die Kosten später darüber, ist erneut eine Freigabe nötig.', cost_limit_setting: 'Kosten-Freigabegrenze je Auftrag (€ netto)', cost_limit_setting_hint: 'Leer = aus. Übersteigen die bewerteten Kosten eines Auftrags (Ist + Schätzung, ohne unbewertete Positionen) diesen Betrag, wird die Fuhrparkleitung informiert und der Auftrag als „Kostenfreigabe ausstehend“ markiert. Die Werkstatt sieht keine Beträge.', todo_cost_approval: 'Kostenfreigabe ausstehend', pk_cost_limit: 'Kostenfreigabe nötig', pk_cost_approved: 'Kosten freigegeben' });
Object.assign(STRINGS.uk, { cost_approval_pending: 'Очікує погодження витрат', cost_approval_hint_mgr: 'Оцінені витрати (факт + оцінка) перевищують встановлений ліміт або останню погоджену суму. Перевірте та натисніть «Погодити витрати».', cost_approval_hint_ws: 'Витрати перевищують ліміт погодження. Перед подальшими великими роботами/замовленнями дочекайтеся погодження керівника автопарку (роботи, важливі для безпеки, не відкладайте).', cost_limit: 'Ліміт погодження', cost_approved_upto: 'погоджено до', act_approve_costs: 'Погодити витрати', act_cost_limit_exceeded: 'Витрати понад ліміт', cost_approve_hint: 'Погоджує поточну суму. Якщо витрати згодом зростуть понад неї, потрібне нове погодження.', cost_limit_setting: 'Ліміт погодження витрат на замовлення (€ нетто)', cost_limit_setting_hint: 'Порожньо = вимкнено. Якщо оцінені витрати замовлення (факт + оцінка, без неоцінених позицій) перевищують цю суму, керівник автопарку отримує сповіщення, а замовлення позначається «Очікує погодження витрат». Майстерня не бачить сум.', todo_cost_approval: 'Очікує погодження витрат', pk_cost_limit: 'Потрібне погодження витрат', pk_cost_approved: 'Витрати погоджено' });
Object.assign(STRINGS.en, { cost_approval_pending: 'Cost approval pending', cost_approval_hint_mgr: 'The valued costs (actual + estimate) exceed the configured approval limit or the last approved amount. Please review and “Approve costs”.', cost_approval_hint_ws: 'Costs exceed the approval limit. Please wait for fleet management approval before further major work/orders (do not postpone safety-relevant work).', cost_limit: 'Approval limit', cost_approved_upto: 'approved up to', act_approve_costs: 'Approve costs', act_cost_limit_exceeded: 'Costs above approval limit', cost_approve_hint: 'Approves the current amount. If costs later rise above it, a new approval is required.', cost_limit_setting: 'Cost approval limit per order (€ net)', cost_limit_setting_hint: 'Empty = off. If the valued costs of an order (actual + estimate, excluding unvalued items) exceed this amount, fleet management is notified and the order is marked “Cost approval pending”. The workshop does not see amounts.', todo_cost_approval: 'Cost approval pending', pk_cost_limit: 'Cost approval needed', pk_cost_approved: 'Costs approved' });
Object.assign(STRINGS.de, { help_costlimit_t: 'Kosten-Freigabegrenze', help_costlimit_s: 'Der Inhaber kann unter Einstellungen eine Grenze je Auftrag in € netto eintragen (leer = aus) – die App gibt keinen Betrag vor.|Übersteigen die bewerteten Kosten (Ist + Schätzung) die Grenze, erscheint am Auftrag „Kostenfreigabe ausstehend“ und die Fuhrparkleitung erhält einen Hinweis. Positionen ohne Preis zählen nicht mit.|Fuhrparkleitung: Auftrag öffnen → „Kosten freigeben“ mit Vermerk. Die Freigabe gilt bis zum aktuellen Betrag; steigen die Kosten darüber, ist erneut eine Freigabe nötig.|Werkstatt: Sie sehen nur „Kostenfreigabe ausstehend“, keine Beträge. Größere weitere Arbeiten oder Bestellungen erst nach Freigabe – sicherheitsrelevante Arbeiten nicht aufschieben.' });
Object.assign(STRINGS.uk, { help_costlimit_t: 'Ліміт погодження витрат', help_costlimit_s: 'Власник може в Налаштуваннях вказати ліміт на замовлення в € нетто (порожньо = вимкнено) – застосунок не задає суму.|Якщо оцінені витрати (факт + оцінка) перевищують ліміт, на замовленні з’являється «Очікує погодження витрат», а керівник автопарку отримує сповіщення. Позиції без ціни не враховуються.|Керівник автопарку: відкрийте замовлення → «Погодити витрати» з приміткою. Погодження діє до поточної суми; якщо витрати зростуть понад неї, потрібне нове погодження.|Майстерня: ви бачите лише «Очікує погодження витрат», без сум. Подальші великі роботи чи замовлення – лише після погодження; роботи, важливі для безпеки, не відкладайте.' });
Object.assign(STRINGS.en, { help_costlimit_t: 'Cost approval limit', help_costlimit_s: 'The owner can enter a limit per order in € net under Settings (empty = off) – the app does not set an amount.|If the valued costs (actual + estimate) exceed the limit, the order shows “Cost approval pending” and fleet management is notified. Items without a price are not counted.|Fleet management: open the order → “Approve costs” with a note. The approval covers the current amount; if costs rise above it, a new approval is required.|Workshop: you only see “Cost approval pending”, no amounts. Further major work or orders only after approval – do not postpone safety-relevant work.' });
